#include <stdio.h>
#include <stdlib.h>

void visit(int graph[][2], int current, int seen[], int order[], int *count) {
    seen[current] = 1;
    order[*count] = current;
    (*count)++;
    for (int i = 0; i < 2; i++) {
        int next = graph[current][i];
        if (!seen[next]) visit(graph, next, seen, order, count);
    }
}

int main(void) {
    int graph[4][2] = {{1, 2}, {0, 3}, {0, 3}, {1, 2}};
    int seen[4] = {0};
    int order[4];
    int count = 0;
    visit(graph, 0, seen, order, &count);
    for (int i = 0; i < count; i++) {
        if (i > 0) printf(" ");
        printf("%d", order[i]);
    }
    printf("\n");
    return 0;
}

#include <algorithm>
#include <iostream>
#include <vector>

void visit(const std::vector<std::vector<int>>& graph, int current,
           std::vector<bool>& seen, std::vector<int>& order) {
    seen[current] = true;
    order.push_back(current);
    for (int next : graph[current]) {
        if (!seen[next]) visit(graph, next, seen, order);
    }
}

int main() {
    std::vector<std::vector<int>> graph = {{1, 2}, {0, 3}, {0, 3}, {1, 2}};
    std::vector<bool> seen(graph.size(), false);
    std::vector<int> order;
    visit(graph, 0, seen, order);
    for (int i = 0; i < static_cast<int>(order.size()); i++) {
        if (i > 0) std::cout << " ";
        std::cout << order[i];
    }
    std::cout << "\n";
    return 0;
}

using System;
using System.Collections.Generic;

int[][] graph = {
    new int[] {1, 2}, new int[] {0, 3},
    new int[] {0, 3}, new int[] {1, 2}
};
bool[] seen = new bool[graph.Length];
List<int> order = new List<int>();
Visit(graph, 0, seen, order);
Console.WriteLine(string.Join(" ", order));

static void Visit(int[][] graph, int current, bool[] seen, List<int> order) {
    seen[current] = true;
    order.Add(current);
    foreach (int next in graph[current]) {
        if (!seen[next]) Visit(graph, next, seen, order);
    }
}

import java.util.*;

class Main {
    static void visit(int[][] graph, int current, boolean[] seen, List<Integer> order) {
        seen[current] = true;
        order.add(current);
        for (int next : graph[current]) {
            if (!seen[next]) visit(graph, next, seen, order);
        }
    }

    public static void main(String[] args) {
        int[][] graph = {{1, 2}, {0, 3}, {0, 3}, {1, 2}};
        boolean[] seen = new boolean[graph.length];
        List<Integer> order = new ArrayList<>();
        visit(graph, 0, seen, order);
        for (int i = 0; i < order.size(); i++) {
            if (i > 0) System.out.print(" ");
            System.out.print(order.get(i));
        }
        System.out.println();
    }
}
